package vn.edu.bookverse.controller;
import jakarta.servlet.annotation.*; import jakarta.servlet.http.*; import java.io.*; import vn.edu.bookverse.service.*; import vn.edu.bookverse.entity.*;
@WebServlet({"","/book","/review"}) public class CatalogServlet_24162040 extends HttpServlet {final CatalogService_24162040 catalog=new CatalogService_24162040(); protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException,jakarta.servlet.ServletException{if(q.getServletPath().equals("/book")){long id=Long.parseLong(q.getParameter("id"));q.setAttribute("book",catalog.books.find(id));q.setAttribute("reviews",catalog.reviews(id));q.getRequestDispatcher("/views/user/book.jsp").forward(q,p);return;}int page=Math.max(1,parse(q.getParameter("page")));long total=catalog.books.count();q.setAttribute("books",catalog.books.page(page,6));q.setAttribute("page",page);q.setAttribute("pages",(int)Math.ceil(total/6d));q.setAttribute("totalBooks",total);q.getRequestDispatcher("/views/user/home.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{User_24162040 u=(User_24162040)q.getSession().getAttribute("user");long id=Long.parseLong(q.getParameter("bookId"));if(u==null){p.sendRedirect("login");return;}catalog.addReview(id,u,parse(q.getParameter("rating")),q.getParameter("content"));p.sendRedirect("book?id="+id);}private int parse(String x){try{return Integer.parseInt(x);}catch(Exception e){return 1;}} }
